// Comparison spec for the HD6309 machines (cocoh, coco3h, dragon64h, tanodr64h).
//
// sweep.asm (generated by gen-sweep.js) is our own firmware, installed in place of the BASIC ROM: it
// runs every 6309-only instruction in every addressing mode, in both emulation and native mode, the
// four TFM variants, and ends in HALT.
//
// The comparison is strict: every register and every cycle count must match MAME, with no allowed
// differences. Where the product (hardware, per the sources) and MAME disagree, the machine is created
// with config.mameCompat, which makes js/cpu/cpu6309.js reproduce MAME 0.289's cycles and flags
// (MAME_DELTA and the mameCompat branches). The reference is MAME 0.289: the table encodes that
// version's behaviour, and a run on another version is informational only.
const path = require('path'), cp = require('child_process');
const { loadEmu, assembleFile, romImage, writeRoms, mameConfigArgs } = require('../lib/firmware');
const { MAME } = require('../lib/mame');
const { REGS_6309: REGS } = require('../lib/regs');

// The ROMs MAME's driver for `system` asks for, in the order it lists them, as [{ name, size }]. With
// `all` false only the first region's ROMs are returned (the ones the firmware replaces); with it true,
// every ROM the driver needs, so the ones this test does not use can be given a filler image of the right
// size (MAME refuses to start without them). Cached per system, since it costs a MAME launch.
const romCache = new Map();
function mameRoms(work, system, all = false) {
  if (!romCache.has(system)) {
    let out = null;
    try {
      const txt = cp.execFileSync(MAME, [system, '-listroms'], { env: Object.assign({}, process.env, { XDG_RUNTIME_DIR: work }), timeout: 30000 }).toString();
      out = [];
      // "name    size CRC(...)": the size column is decimal
      for (const m of txt.matchAll(/^(\S+)\s+(\d+)\s+CRC\(/gm)) out.push({ name: m[1], size: Number(m[2]) });
    } catch (e) { out = null; }
    romCache.set(system, out);
  }
  const list = romCache.get(system);
  if (!list) return null;
  return all ? list : list.filter((r) => !/^(ddos|disk|ados|sdtandy|dos)/.test(r.name));
}


// the registers the trace compares. W, Q, E, F, V and MD are the 6309's own; W/Q are derived from
// E:F and A:B:E:F, so a divergence in any of them shows up in both places.
// the profile's HD6309 sibling: dragon64 -> dragon64h, coco -> cocoh, coco3 -> coco3h, tanodr64 -> tanodr64h
const hd6309 = (id) => `${id}h`;

module.exports = {
  family: '6309',
  trace(profileId, { regenerate = true, work = `/tmp/mame-diff/6309-${profileId}` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const system = profile.mame6309 || hd6309(profile.mame);
    if (!Emu.profiles[profileId]) throw new Error(`no profile ${profileId}`);
    // The vectors sit at the top of the ROM window: $BFF0 for a 16K image (Dragon/CoCo), $FFF0 for the
    // CoCo 3's 32K one. gen-sweep.js takes that base from the environment, then the image is assembled.
    const span = Math.max(...profile.roms.map((s) => s.at + s.size)) - 0x8000;
    // the two variants are separate files, so switching profiles does not leave a stale one behind
    const wide = span === 0x8000, file = wide ? 'sweep32.asm' : 'sweep.asm';
    if (regenerate) {
      process.env.SWEEP_VECTORS = wide ? '$FFF0' : '$BFF0'; process.env.SWEEP_OUT = file;
      delete require.cache[require.resolve('./gen-sweep')];   // it writes on require, so reload it each time
      require('./gen-sweep');
    }
    const asm = assembleFile(path.join(__dirname, file), '6309');
    // The image covers the whole ROM window: 16K for the Dragon/CoCo sockets, 32K for the CoCo 3's single
    // coco3.rom at $8000. The firmware assembles at $8000 and its vectors sit at the top of that window,
    const image = romImage(asm, 0x8000, span, 0x12);
    const slots = {};
    // a slot at $8000 takes the image from its own start; one above it (the CoCo 2 BASIC at $A000)
    // takes the part of the image that address map to, which is where the firmware places it
    for (const sl of profile.roms) slots[sl.id] = image.slice(sl.at - 0x8000, sl.at - 0x8000 + sl.size);
    const files = {};
    const listed = mameRoms(work, system, true);
    const firmware = profile.roms.map((sl) => slots[sl.id]);
    // The firmware goes in under the profile's names. It may also have to go in under a different name the
    // driver asks for -- tanodr64h wants tano_1.ic18/tano_2.ic17 where the profile names d64_1.rom/d64_2.rom
    // -- so a listed name that shares its size with a firmware image, and is not one of the profile's own,
    // gets that image as well. Every other ROM the driver lists (disk controller images) gets a filler of
    // the right size: MAME refuses to start without them, and none is loaded while the firmware runs.
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    if (listed) {
      const mine = new Set(profile.roms.flatMap((sl) => sl.files));
      const known = listed.filter((r) => mine.has(r.name));
      // When the driver asks for names the profile does not use at all (tanodr64h: tano_1.ic18 where the
      // profile says d64_1.rom), the firmware goes in under the listed names instead, matched by size.
      // Otherwise the profile's names already cover the driver's main ROMs and only fillers are needed.
      if (!known.length) {
        const sorted = [...profile.roms].sort((a, b) => a.at - b.at);
        for (const sl of sorted) {
          const r = listed.find((x) => x.size === sl.size && !(x.name in files));
          if (r) files[r.name] = slots[sl.id];
        }
      }
      // the disk ROM is not part of this test, but MAME refuses to start without one: a filler of the right
      // size for every ROM the driver lists that nothing has filled
      for (const r of listed) if (!(r.name in files)) files[r.name] = new Uint8Array(r.size).fill(0x12);
    } else {
      // no MAME to ask: the profile's own DOS/disk sockets get a filler, as before
      const dos = profile.roms.find((s) => s.id === 'dos');
      if (dos) for (const f of dos.files) files[f] = new Uint8Array(dos.size).fill(0x12);
    }
    return {
      label: `${profileId} (${system})`, system, work, seconds: 4, args: ['-ext', '', ...mameConfigArgs({})],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'), slots,
      install: () => writeRoms(work, system, files),
      machine: () => {
        const m = Emu.createMachine(profileId, { cpu: '6309', mameCompat: true });
        m.setRoms(slots);
        m.reset(true);
        return m;
      },
      instructions: 400000,
    };
  },
};
